/**
 * Internal failure reporting.
 *
 * @remarks
 * The library's own failures are none of the host application's business — but
 * they must be *observable*, or a silently degraded vault looks like a working one.
 * So each distinct failure `stage` is reported exactly once: through the logger
 * under a reserved prefix (console-only, never persisted) and through the
 * `onInternalError` option. Repeats are suppressed because a failure inside the
 * error path would otherwise produce one warning per captured error.
 *
 * @packageDocumentation
 */

import { getLoggerController } from '../logger/logger.js';
import { getState } from './state.js';

/** Stages already reported in this initialization. */
const reported = new Set<string>();

/** Render a short description of a thrown value without ever throwing. */
function describe(error: unknown): string {
  try {
    if (error === null) return 'null';
    if (error === undefined) return 'undefined';
    if (typeof error === 'string') return error;
    if (typeof error === 'object') {
      const name: unknown = (error as { name?: unknown }).name;
      const message: unknown = (error as { message?: unknown }).message;
      const parts = [
        typeof name === 'string' ? name : '',
        typeof message === 'string' ? message : '',
      ];
      const joined = parts.filter((part) => part.length > 0).join(': ');
      if (joined.length > 0) return joined;
      return Object.prototype.toString.call(error);
    }
    return String(error);
  } catch {
    return '[unprintable]';
  }
}

/**
 * Report a failure inside the library itself.
 *
 * @param stage - a stable, low-cardinality stage name, e.g. `'persist'`
 * @param error - the thrown value
 *
 * @remarks
 * Never throws and never rethrows `error`. Each `<stage>` is reported once per
 * initialization; use {@link resetInternalFailures} to clear the suppression set.
 *
 * @example
 * ```ts
 * import { reportInternalFailure } from '@codewithrajat/rm-logvault';
 *
 * try {
 *   await risky();
 * } catch (error) {
 *   reportInternalFailure('persist', error);
 * }
 * ```
 */
export function reportInternalFailure(stage: string, error: unknown): void {
  try {
    if (reported.has(stage)) return;
    reported.add(stage);

    const message = `[Telemetry] ${stage} failed: ${describe(error)}`;
    getLoggerController().emitInternal('warn', message, []);

    const onInternalError = getState().options?.onInternalError;
    if (onInternalError !== undefined) {
      try {
        onInternalError(stage, error);
      } catch {
        // An observer that throws is not our problem.
      }
    }
  } catch {
    // Reporting must never throw.
  }
}

/**
 * Report a stage-level note (not an exception), e.g. a rate-limit summary.
 *
 * @param stage - the stage name, used for the message
 * @param detail - extra human-readable detail
 *
 * @remarks
 * Routed through the same once-per-stage suppression as
 * {@link reportInternalFailure}, so a storm collapses to one line.
 */
export function reportInternalNote(stage: string, detail: string): void {
  try {
    if (reported.has(stage)) return;
    reported.add(stage);
    getLoggerController().emitInternal('warn', `[Telemetry] ${stage}: ${detail}`, []);
    const onInternalError = getState().options?.onInternalError;
    if (onInternalError !== undefined) {
      try {
        onInternalError(stage, new Error(detail));
      } catch {
        // ignore
      }
    }
  } catch {
    // ignore
  }
}

/**
 * Clear the suppression set.
 *
 * @remarks
 * Called by `initTelemetry` so a fresh initialization reports its own failures,
 * rather than inheriting a previous run's "already reported" state.
 */
export function resetInternalFailures(): void {
  reported.clear();
}
