/**
 * Process-wide singleton state and teardown bookkeeping.
 *
 * @remarks
 * Two hazards motivate this module:
 *
 * 1. **Duplicate copies.** Microfrontends and Module Federation routinely end up
 *    with two copies of the same package in one page. If each copy kept its own
 *    module-scoped state, installing global listeners twice would capture every
 *    error twice — and, because the adapter entries inline their own copy of the
 *    error pipeline, a capture made through one of them would be buffered by a
 *    copy whose buffer is never drained. The state therefore lives on
 *    `globalThis[Symbol.for('logvault@1')]`, which is shared by every copy.
 * 2. **Leaked listeners and timers.** `destroyTelemetry()` must leave no trace, so
 *    every listener and timer is registered with the {@link CleanupRegistry} rather
 *    than created ad hoc.
 *
 * @packageDocumentation
 */

import type { BufferedError, ErrorTracker } from '../errors/captureError.js';
import { SINGLETON_KEY } from '../errors/constants.js';
import type { StorageState, TelemetryRepository } from '../storage/storage.types.js';
import type { ResolvedTelemetryOptions } from './config.js';
import type { EventEmitter } from './events.js';
import { newPageLoadId } from './ids.js';

// ---------------------------------------------------------------------------
// Cleanup registry
// ---------------------------------------------------------------------------

/**
 * Tracks every side effect the library installs so `destroyTelemetry()` can undo
 * all of them deterministically.
 */
export interface CleanupRegistry {
  /** Register an arbitrary teardown function. */
  add(teardown: () => void): void;
  /** Register a listener; removal is automatic on cleanup. */
  addListener(
    target: EventTarget,
    type: string,
    handler: EventListenerOrEventListenerObject,
    options?: AddEventListenerOptions | boolean,
  ): void;
  /** Register a timeout; clearing is automatic on cleanup. */
  setTimeout(handler: () => void, ms: number): number;
  /** Register an interval; clearing is automatic on cleanup. */
  setInterval(handler: () => void, ms: number): number;
  /** Run every teardown exactly once, in reverse registration order. */
  run(): void;
  /** Whether {@link CleanupRegistry.run} has already been called. */
  readonly ran: boolean;
}

/** Create a {@link CleanupRegistry}. */
export function createCleanupRegistry(): CleanupRegistry {
  const teardowns: (() => void)[] = [];
  let ran = false;

  const run = (): void => {
    if (ran) return;
    ran = true;
    // Reverse order so later registrations unwind before their dependencies.
    for (let index = teardowns.length - 1; index >= 0; index -= 1) {
      const teardown = teardowns[index];
      if (teardown === undefined) continue;
      try {
        teardown();
      } catch {
        // Teardown must never throw out of `destroyTelemetry`.
      }
    }
    teardowns.length = 0;
  };

  return {
    add: (teardown: () => void): void => {
      if (ran) {
        // Registering after cleanup means tearing down immediately.
        try {
          teardown();
        } catch {
          // ignore
        }
        return;
      }
      teardowns.push(teardown);
    },
    addListener: (
      target: EventTarget,
      type: string,
      handler: EventListenerOrEventListenerObject,
      options?: AddEventListenerOptions | boolean,
    ): void => {
      try {
        target.addEventListener(type, handler, options);
      } catch {
        return;
      }
      const capture = typeof options === 'object' ? options.capture === true : options === true;
      teardowns.push(() => {
        try {
          target.removeEventListener(type, handler, capture);
        } catch {
          // ignore
        }
      });
    },
    setTimeout: (handler: () => void, ms: number): number => {
      const id = setTimeout(() => {
        try {
          handler();
        } catch {
          // ignore
        }
      }, ms) as unknown as number;
      teardowns.push(() => {
        clearTimeout(id);
      });
      return id;
    },
    setInterval: (handler: () => void, ms: number): number => {
      const id = setInterval(() => {
        try {
          handler();
        } catch {
          // ignore
        }
      }, ms) as unknown as number;
      teardowns.push(() => {
        clearInterval(id);
      });
      return id;
    },
    run,
    get ran(): boolean {
      return ran;
    },
  };
}

// ---------------------------------------------------------------------------
// Singleton state
// ---------------------------------------------------------------------------

/** Mutable process-wide state shared by every copy of the library in one realm. */
export interface TelemetryState {
  /** Marker used by the cross-copy type guard. */
  readonly __logvaultState: true;
  /** Whether `initTelemetry` has completed and not yet been destroyed. */
  initialized: boolean;
  /** Resolved configuration, or `null` before init / after destroy. */
  options: ResolvedTelemetryOptions | null;
  /** The active persistence backend, or `null`. */
  repository: TelemetryRepository | null;
  /** Whether persistence is usable, disabled, or unavailable. */
  storageState: StorageState;
  /** Last known number of error records still awaiting upload. */
  pendingErrors: number;
  /** Last known number of log records still awaiting upload. */
  pendingLogs: number;
  /** Identifier shared by every record produced during this page load. */
  pageLoadId: string;
  /** Teardown for the current initialization. Replaced on re-init. */
  teardown: (() => void) | null;
  /** Flush hook for the current initialization. */
  flush: (() => Promise<void>) | null;
  /** Requeue hook that moves terminally-failed records back to `pending`. */
  retryFailed: (() => Promise<number>) | null;
  /** Cleanup registry for the current initialization. */
  cleanup: CleanupRegistry;
  /**
   * The live error tracker, or `null` before init / after destroy.
   *
   * @remarks
   * Deliberately not module-scoped in `captureError`. The adapter entries are
   * separate bundles that inline their own copy of the error pipeline, so a
   * module-scoped tracker left an adapter dispatching into a buffer nothing ever
   * drained — which is silent, because nothing failed. Holding it here is what
   * lets *any* copy of the library resolve the one live tracker.
   */
  errorTracker: ErrorTracker | null;
  /** Errors captured before initialization, shared so one copy's replay drains them all. */
  preInitErrors: BufferedError[];
  /** Whether capture is globally suppressed (`enabled: false`). Shared by every copy. */
  captureSuppressed: boolean;
  /**
   * The observer emitter for the current installation, or `null`.
   *
   * @remarks
   * Held here rather than in `init.ts` module scope for the same reason the error
   * tracker is: an adapter bundle inlines its own copy of the pipeline, and only
   * shared state gives every copy the one live emitter.
   */
  eventEmitter: EventEmitter | null;
}

/** Type guard for the shared singleton. */
function isTelemetryState(value: unknown): value is TelemetryState {
  return (
    value !== null &&
    typeof value === 'object' &&
    (value as { __logvaultState?: unknown }).__logvaultState === true
  );
}

/** Build a fresh state object. */
function createState(): TelemetryState {
  return {
    __logvaultState: true,
    initialized: false,
    options: null,
    repository: null,
    storageState: 'disabled',
    pendingErrors: 0,
    pendingLogs: 0,
    pageLoadId: newPageLoadId(),
    teardown: null,
    flush: null,
    retryFailed: null,
    cleanup: createCleanupRegistry(),
    errorTracker: null,
    preInitErrors: [],
    captureSuppressed: false,
    eventEmitter: null,
  };
}

/**
 * Backfill members an older build of the library may not have created.
 *
 * @remarks
 * The first copy of the package to call {@link getState} installs the shared
 * object, and two versions can be loaded in one page. A state object written
 * before these members existed is repaired in place rather than rejected:
 * rejecting it would hand this copy a private object and split capture in two,
 * and leaving it broken would make `captureError` dereference `undefined`.
 */
function repairState(state: TelemetryState): TelemetryState {
  const mutable: Partial<TelemetryState> = state;
  if (mutable.errorTracker === undefined) mutable.errorTracker = null;
  if (!Array.isArray(mutable.preInitErrors)) mutable.preInitErrors = [];
  if (typeof mutable.captureSuppressed !== 'boolean') mutable.captureSuppressed = false;
  if (mutable.eventEmitter === undefined) mutable.eventEmitter = null;
  return state;
}

/** Cache so repeated lookups stay cheap. */
let cached: TelemetryState | undefined;

/**
 * Read (or lazily create) the shared state object.
 *
 * @returns the process-wide {@link TelemetryState}
 *
 * @remarks
 * The object is installed on `globalThis` with `Symbol.for`, so a second bundled
 * copy of the library resolves the *same* instance and merges into one set of
 * listeners instead of duplicating capture.
 *
 * @example
 * ```ts
 * import { getState } from '@codewithrajat/rm-logvault';
 *
 * getState().initialized;   // false before initTelemetry()
 * ```
 */
export function getState(): TelemetryState {
  if (cached !== undefined) return cached;

  try {
    const existing: unknown = Reflect.get(globalThis, SINGLETON_KEY);
    if (isTelemetryState(existing)) {
      cached = repairState(existing);
      return cached;
    }
  } catch {
    // Fall through and create a private instance.
  }

  const fresh = createState();
  try {
    Object.defineProperty(globalThis, SINGLETON_KEY, {
      value: fresh,
      writable: false,
      enumerable: false,
      configurable: false,
    });
  } catch {
    // A frozen globalThis is unusual but survivable: we still return usable state.
  }
  cached = fresh;
  return cached;
}

/**
 * Reset the shared state to its pre-init values.
 *
 * @remarks
 * Used by `destroyTelemetry()` and by tests. The state object identity is stable,
 * because other copies of the library hold a reference to it.
 */
export function resetState(): void {
  const state = getState();
  state.initialized = false;
  state.options = null;
  state.repository = null;
  state.storageState = 'disabled';
  state.pendingErrors = 0;
  state.pendingLogs = 0;
  state.teardown = null;
  state.flush = null;
  state.retryFailed = null;
  state.cleanup = createCleanupRegistry();
  state.errorTracker = null;
  state.captureSuppressed = false;
  state.eventEmitter = null;
  // Truncated rather than replaced: another copy of the library holds this array.
  state.preInitErrors.length = 0;
}
