/**
 * The single error ingestion point.
 *
 * @remarks
 * Every source — global handlers, framework adapters, the HTTP adapters, and
 * manual calls — funnels through `captureError`. That is what makes the
 * guarantees in this file global rather than per-integration:
 *
 * - **It cannot throw.** The whole body is guarded and failures go to
 *   {@link reportInternalFailure}.
 * - **It cannot recurse.** A `capturing` flag drops any error raised while the
 *   pipeline is already running, so an error inside sanitisation cannot produce a
 *   second capture, and so on.
 * - **It cannot double count.** A `WeakSet` remembers object/function errors, so
 *   the same `Error` arriving through a React boundary *and* `window.onerror`
 *   *and* an axios interceptor becomes exactly one record.
 * - **It cannot flood.** A fixed-window rate limit drops excess and reports one
 *   summary when the window rolls.
 * - **It cannot lose pre-init errors.** Failures thrown before `initTelemetry`
 *   runs are normalised immediately (bounded, sanitized, no live object graph
 *   retained) and replayed once application metadata is known.
 *
 * @packageDocumentation
 */

import type { ResolvedTelemetryOptions } from '../core/config.js';
import { now } from '../core/env.js';
import { newId } from '../core/ids.js';
import { reportInternalFailure, reportInternalNote } from '../core/internal.js';
import { currentEnvironment, currentPageInfo } from '../core/page.js';
import { createSerialQueue } from '../core/queue.js';
import { createRateLimiter } from '../core/rateLimit.js';
import { getState } from '../core/state.js';
import type { Maybe, Timestamp } from '../core/types.js';
import type { ErrorRepository } from '../storage/storage.types.js';
import type { FetchFailure, FetchRequestInfo } from './apiContext.js';
import { buildApiErrorContext, buildFetchErrorContext } from './apiContext.js';
import {
  MAX_COMPONENT_STACK_LENGTH,
  MAX_MESSAGE_LENGTH,
  MAX_STACK_LENGTH,
  MAX_TAG_KEY_LENGTH,
  MAX_TAG_VALUE_LENGTH,
  MAX_TAGS,
  PRE_INIT_ERROR_BUFFER_SIZE,
  UNHANDLED_SOURCES,
} from './constants.js';
import { resolveErrorContext } from './contextBuilders.js';
import { fingerprint } from './fingerprint.js';
import { normalizeError } from './normalize.js';
import { reduceErrorPayload } from './payload.js';
import { getDefaultSanitizer } from './sanitize.js';
import type { ErrorContext, ErrorRecord, NormalizedError } from './types.js';

/** Options for {@link createErrorTracker}. */
export interface ErrorTrackerOptions {
  /** Where records are persisted. */
  readonly repository: ErrorRepository;
  /** Resolved configuration. */
  readonly options: ResolvedTelemetryOptions;
  /** Called for every accepted record, so the sync manager can pull a timer forward. */
  readonly onRecord?: Maybe<(record: ErrorRecord) => void>;
}

/**
 * The internal error pipeline for one initialization.
 *
 * @remarks
 * Exposed for advanced wiring and tests. Applications normally use the
 * module-level {@link captureError} instead.
 */
export interface ErrorTracker {
  /** Normalise, deduplicate and persist a thrown value. Never throws. */
  capture(error: unknown, ctx?: ErrorContext): void;
  /** Ingest an already-normalised error (used to replay the pre-init buffer). */
  captureNormalized(
    normalized: NormalizedError,
    ctx: Maybe<ErrorContext>,
    timestamp: Timestamp,
  ): void;
  /** Observe accepted records. Returns an unsubscribe function. */
  subscribe(listener: (record: ErrorRecord) => void): () => void;
  /** Events dropped by the rate limiter in the current window. */
  droppedByRateLimit(): number;
  /** Stop accepting records. */
  destroy(): void;
  /** Persist everything queued and wait for the write chain to settle. */
  flush(): Promise<void>;
}

/** An error captured before `initTelemetry` ran. */
export interface BufferedError {
  readonly normalized: NormalizedError;
  readonly ctx: Maybe<ErrorContext>;
  readonly timestamp: Timestamp;
}

/**
 * Suppress or restore capture process-wide.
 *
 * @param value - `true` drops every capture without buffering
 *
 * @remarks
 * Used by `initTelemetry` when `enabled: false`, so a master-disabled installation
 * neither stores nor buffers errors. The flag lives on the shared state object
 * rather than in module scope, so a second copy of the library honours it too.
 * Exported for tests.
 */
export function setCaptureSuppressed(value: boolean): void {
  try {
    getState().captureSuppressed = value === true;
  } catch (failure) {
    reportInternalFailure('capture-suppression', failure);
  }
}

/** An error record with its `readonly` modifiers stripped, for incremental assembly. */
type MutableErrorRecord = { -readonly [K in keyof ErrorRecord]: ErrorRecord[K] };

/** Sanitize a caller-supplied tag bag. */
function sanitizeTags(
  tags: Readonly<Record<string, string>> | undefined,
): Record<string, string> | undefined {
  if (tags === undefined) return undefined;
  const sanitizer = getDefaultSanitizer();
  const out: Record<string, string> = {};
  let count = 0;
  try {
    for (const [key, value] of Object.entries(tags)) {
      if (count >= MAX_TAGS) break;
      const safeKey = sanitizer.text(key, MAX_TAG_KEY_LENGTH);
      if (safeKey.length === 0) continue;
      out[safeKey] = sanitizer.text(
        typeof value === 'string' ? value : String(value),
        MAX_TAG_VALUE_LENGTH,
      );
      count += 1;
    }
  } catch {
    return undefined;
  }
  return count > 0 ? out : undefined;
}

/** Sanitize a caller-supplied extra bag. */
function sanitizeExtra(
  extra: Readonly<Record<string, unknown>> | undefined,
): Record<string, unknown> | undefined {
  if (extra === undefined) return undefined;
  try {
    const sanitized = getDefaultSanitizer().value(extra);
    if (sanitized !== null && typeof sanitized === 'object' && !Array.isArray(sanitized)) {
      const entries = Object.entries(sanitized as Record<string, unknown>);
      return entries.length > 0 ? (sanitized as Record<string, unknown>) : undefined;
    }
    return undefined;
  } catch {
    return undefined;
  }
}

/** Whether a value is thenable. */
function isThenable(value: unknown): value is PromiseLike<unknown> {
  return (
    value !== null &&
    (typeof value === 'object' || typeof value === 'function') &&
    typeof (value as { then?: unknown }).then === 'function'
  );
}

/**
 * Create the error tracker.
 *
 * @param trackerOptions - see {@link ErrorTrackerOptions}
 * @returns an {@link ErrorTracker}
 *
 * @example
 * ```ts
 * import { createErrorTracker, createErrorRepository } from '@codewithrajat/rm-logvault';
 *
 * const repository = createErrorRepository({ dbName: 'rm-logvault-errors' });
 * const tracker = createErrorTracker({ repository, options: resolveOptions() });
 * tracker.capture(new Error('boom'));
 * ```
 */
export function createErrorTracker(trackerOptions: ErrorTrackerOptions): ErrorTracker {
  const { repository, options: config } = trackerOptions;
  const queue = createSerialQueue();

  /** Objects already routed through the pipeline. */
  const seen = new WeakSet<object>();
  const listeners = new Set<(record: ErrorRecord) => void>();

  let capturing = false;
  let destroyed = false;

  const limiter = createRateLimiter(config.errors.maxEventsPerMinute, (dropped) => {
    reportInternalNote('rate-limit', `${String(dropped)} dropped`);
  });

  /** Whether the caller's consent gate currently permits capture. */
  const consentGranted = (): boolean => {
    const consent = config.consent;
    if (consent === undefined) return true;
    try {
      return consent() === true;
    } catch {
      // A throwing consent gate fails closed: do not store.
      return false;
    }
  };

  /** Notify subscribers that a record was accepted. */
  const emitRecord = (record: ErrorRecord): void => {
    for (const listener of [...listeners]) {
      try {
        listener(record);
      } catch {
        // Observers must not break ingestion.
      }
    }
    try {
      trackerOptions.onRecord?.(record);
    } catch {
      // ignore
    }
  };

  /** Build a fully-sanitized record from a normalised error. */
  const buildRecord = (
    normalized: NormalizedError,
    ctx: Maybe<ErrorContext>,
    timestamp: Timestamp,
  ): ErrorRecord => {
    const sanitizer = getDefaultSanitizer();
    const source = ctx?.source ?? 'manual';

    const name = sanitizer.text(normalized.name, MAX_MESSAGE_LENGTH);
    const message = sanitizer.text(normalized.message, MAX_MESSAGE_LENGTH);
    const stack =
      normalized.stack === undefined
        ? undefined
        : sanitizer.stack(normalized.stack, MAX_STACK_LENGTH);
    const componentStack =
      ctx?.componentStack === undefined
        ? undefined
        : sanitizer.stack(ctx.componentStack, MAX_COMPONENT_STACK_LENGTH);

    const causes =
      normalized.causes === undefined
        ? undefined
        : normalized.causes.map((cause) => {
            const mapped: { name: string; message: string; stack?: string } = {
              name: sanitizer.text(cause.name, MAX_MESSAGE_LENGTH),
              message: sanitizer.text(cause.message, MAX_MESSAGE_LENGTH),
            };
            if (cause.stack !== undefined) {
              mapped.stack = sanitizer.stack(cause.stack, MAX_STACK_LENGTH);
            }
            return mapped;
          });

    const page = currentPageInfo();
    const environment = currentEnvironment(config);

    // Defaults derived from the source, per the documented behaviour table.
    const severity = ctx?.severity ?? (normalized.isChunkError ? 'fatal' : ('error' as const));
    const category = ctx?.category ?? normalized.category ?? ('runtime' as const);
    const handled = ctx?.handled ?? !UNHANDLED_SOURCES.has(source);

    // The fingerprint is computed from the sanitized values above, never the raw
    // input, so a secret can never influence an index key.
    const fingerprintValue = fingerprint({
      source,
      category,
      name,
      message,
      stack,
      componentStack,
      route: page.route,
      api: ctx?.api,
      event: ctx?.event,
      location: ctx?.location,
    });

    const record: MutableErrorRecord = {
      schemaVersion: 1,
      id: newId(),
      fingerprint: fingerprintValue,
      uploadStatus: 'pending',
      uploadAttempts: 0,
      source,
      severity,
      category,
      handled,
      thrownType: normalized.thrownType,
      name,
      message,
      page,
      environment,
      timestamp,
      firstSeen: timestamp,
      lastSeen: timestamp,
      occurrenceCount: 1,
    };

    if (stack !== undefined) record.stack = stack;
    if (causes !== undefined) record.causes = causes;
    if (componentStack !== undefined) record.componentStack = componentStack;
    if (ctx?.location !== undefined) record.location = ctx.location;
    if (ctx?.api !== undefined) record.api = ctx.api;
    if (ctx?.event !== undefined) record.event = ctx.event;

    const tags = sanitizeTags(ctx?.tags);
    if (tags !== undefined) record.tags = tags;

    const extra = sanitizeExtra(ctx?.extra);
    if (extra !== undefined) record.extra = extra;

    return record;
  };

  /** The pipeline body. Callers must hold the `capturing` flag. */
  const ingest = (
    normalized: NormalizedError,
    ctx: Maybe<ErrorContext>,
    timestamp: Timestamp,
  ): void => {
    if (destroyed) return;
    if (!config.errors.enabled) return;
    if (!consentGranted()) return;
    if (!limiter.allow()) return;

    let record = buildRecord(normalized, ctx, timestamp);

    const beforeCapture = config.errors.beforeCapture;
    if (beforeCapture !== undefined) {
      try {
        const replacement = beforeCapture(record);
        if (replacement === null) return;
        record = replacement;
      } catch (error) {
        reportInternalFailure('beforeCapture', error);
      }
    }

    const fitted = reduceErrorPayload(record, config.errors.maxPayloadBytes);
    if (fitted === null) {
      reportInternalFailure(
        'payload-limit',
        new Error('error record exceeded its payload budget at every reduction tier'),
      );
      return;
    }

    // Persistence is queued so writes keep their order and one failure cannot
    // poison the chain. The promise is intentionally not awaited: captureError is
    // synchronous and must never make the caller wait on IndexedDB. Its result is
    // still inspected, because a write that fails here — quota, serialization, a
    // store that vanished — would otherwise leave no trace at all. The log tracker
    // reports its own failures; an unreported error write is indistinguishable from
    // a capture that never happened. The stage is deliberately not `'persist'`,
    // which the log tracker owns and which `reportInternalFailure` emits only once
    // per initialization.
    void queue
      .push(() => repository.save(fitted))
      .then((result) => {
        if (result !== undefined && !result.ok) {
          reportInternalFailure('error-persist', result.reason);
        }
      });
    emitRecord(fitted);
  };

  /** Acquire the re-entrancy guard. */
  const acquire = (): boolean => {
    if (capturing) return false;
    capturing = true;
    return true;
  };

  return {
    capture: (error: unknown, ctx?: ErrorContext): void => {
      try {
        if (destroyed || !config.errors.enabled) return;

        // Layer (a) of deduplication: object identity.
        if (error !== null && (typeof error === 'object' || typeof error === 'function')) {
          const object = error as object;
          if (seen.has(object)) return;
          seen.add(object);
        }

        if (!acquire()) return;
        try {
          // Registered builders classify the error before the record is built, so
          // a category, severity or tag a builder contributes is indistinguishable
          // in the output from one the caller passed. The caller's own fields win
          // where both are present.
          const enriched = resolveErrorContext(error, ctx);
          ingest(normalizeError(error), enriched, enriched.timestamp ?? now());
        } finally {
          capturing = false;
        }
      } catch (failure) {
        capturing = false;
        reportInternalFailure('capture', failure);
      }
    },

    captureNormalized: (
      normalized: NormalizedError,
      ctx: Maybe<ErrorContext>,
      timestamp: Timestamp,
    ): void => {
      try {
        if (destroyed || !config.errors.enabled) return;
        if (!acquire()) return;
        try {
          ingest(normalized, ctx, timestamp);
        } finally {
          capturing = false;
        }
      } catch (failure) {
        capturing = false;
        reportInternalFailure('capture', failure);
      }
    },

    subscribe: (listener: (record: ErrorRecord) => void): (() => void) => {
      listeners.add(listener);
      return (): void => {
        listeners.delete(listener);
      };
    },

    droppedByRateLimit: (): number => limiter.dropped(),

    destroy: (): void => {
      destroyed = true;
      listeners.clear();
      queue.clear();
    },

    flush: async (): Promise<void> => {
      await queue.drain();
    },
  };
}

/**
 * Capture anything that was thrown.
 *
 * @param error - the thrown value. Any type is accepted, including `null`, a
 * `Symbol`, a hostile Proxy or an `AggregateError`.
 * @param ctx - optional source, tags, severity and correlation context
 *
 * @remarks
 * This function **never throws** and never returns a rejection. It is safe to call
 * from a `catch` block, from a `window.onerror` handler, or from a React error
 * boundary without any further guarding. Calling it before `initTelemetry` buffers
 * the error (up to 50) and replays it once application metadata is known.
 *
 * @example
 * ```ts
 * import { captureError } from '@codewithrajat/rm-logvault';
 *
 * try {
 *   checkout();
 * } catch (error) {
 *   captureError(error, {
 *     source: 'manual',
 *     tags: { flow: 'checkout' },
 *     extra: { cartId },
 *   });
 * }
 * ```
 */
export function captureError(error: unknown, ctx?: ErrorContext): void {
  try {
    const state = getState();
    if (state.captureSuppressed) return;
    const tracker = state.errorTracker;
    if (tracker !== null) {
      tracker.capture(error, ctx);
      return;
    }
    // Before initialization the options are unknown, so normalise immediately and
    // keep only bounded, sanitized data — never a live reference to the caller's
    // object graph.
    const buffer = state.preInitErrors;
    if (buffer.length >= PRE_INIT_ERROR_BUFFER_SIZE) return;
    buffer.push({
      normalized: normalizeError(error),
      ctx: ctx ?? undefined,
      timestamp: ctx?.timestamp ?? now(),
    });
  } catch (failure) {
    reportInternalFailure('capture', failure);
  }
}

/**
 * Install the active tracker.
 *
 * @param tracker - the tracker to use, or `null` on destroy
 *
 * @remarks
 * Written to the shared state object, not to module scope, so a copy of the
 * library inlined into an adapter bundle resolves the same tracker. Intended for
 * `initTelemetry`/`destroyTelemetry`. Exported for tests.
 */
export function setErrorTracker(tracker: ErrorTracker | null): void {
  try {
    getState().errorTracker = tracker;
  } catch (failure) {
    reportInternalFailure('set-tracker', failure);
  }
}

/**
 * Replay errors captured before initialization.
 *
 * @param tracker - the tracker to replay into
 * @returns the number of buffered errors replayed
 *
 * @remarks
 * `initTelemetry` calls this after installing the tracker, which is what allows a
 * fatal error thrown during module evaluation — before the app could call
 * `initTelemetry` — to still appear in the diagnostics report, complete with
 * application metadata.
 */
export function flushPreInitErrors(tracker: ErrorTracker): number {
  try {
    const buffer = getState().preInitErrors;
    if (buffer.length === 0) return 0;
    const buffered = buffer.splice(0, buffer.length);
    for (const entry of buffered) {
      try {
        tracker.captureNormalized(entry.normalized, entry.ctx, entry.timestamp);
      } catch {
        // One unusable entry must not abandon the rest of the buffer.
      }
    }
    return buffered.length;
  } catch {
    // A state object we cannot read is not worth failing initialization over.
    return 0;
  }
}

/** How many pre-init errors are currently held. */
export function preInitErrorCount(): number {
  try {
    return getState().preInitErrors.length;
  } catch {
    return 0;
  }
}

/** Drop every buffered pre-init error. Called by `destroyTelemetry`. */
export function clearPreInitErrors(): void {
  try {
    getState().preInitErrors.length = 0;
  } catch {
    // Nothing to clear is the same outcome as a successful clear.
  }
}

/**
 * Wrap a handler so a throw or rejection is captured **and then re-thrown**.
 *
 * @param handler - the function to run
 * @param ctx - optional context; `source` defaults to `'event-handler'`
 * @returns exactly what `handler` returned
 *
 * @remarks
 * The error is captured before it propagates, so the application's own error
 * handling is unchanged. For an async handler the returned promise rejects with
 * the **same** error value, not a wrapper.
 *
 * @example
 * ```ts
 * import { withErrorCapture } from '@codewithrajat/rm-logvault';
 *
 * button.addEventListener('click', withErrorCapture(async () => {
 *   await submitOrder();
 * }, { tags: { flow: 'checkout' } }));
 * ```
 */
export function withErrorCapture<T>(handler: () => T, ctx?: ErrorContext): T {
  const context: ErrorContext = { ...ctx, source: ctx?.source ?? 'event-handler' };
  try {
    const result = handler();
    if (isThenable(result)) {
      return result.then(
        (value) => value,
        (error: unknown) => {
          captureError(error, context);
          throw error;
        },
      ) as T;
    }
    return result;
  } catch (error) {
    captureError(error, context);
    throw error;
  }
}

/**
 * Capture an HTTP client failure with full request context.
 *
 * @param error - the axios-shaped rejection (or any thrown value)
 * @param startedAt - timestamp captured before the request was issued, used to
 * compute `api.duration`
 *
 * @remarks
 * Only an allow-list of request metadata is read — method, url, status,
 * statusText, code, timeout, duration and the first present correlation header.
 * Bodies, parameters, cookies and arbitrary headers are never touched.
 *
 * @example
 * ```ts
 * import { captureApiError } from '@codewithrajat/rm-logvault';
 *
 * axios.interceptors.response.use(undefined, (error) => {
 *   captureApiError(error, error.config?.metadata?.startedAt);
 *   return Promise.reject(error);
 * });
 * ```
 */
export function captureApiError(error: unknown, startedAt?: number): void {
  try {
    const classification = buildApiErrorContext(error, startedAt);
    captureError(error, {
      source: 'api',
      api: classification.api,
      category: classification.category,
      severity: classification.severity,
    });
  } catch (failure) {
    reportInternalFailure('capture-api', failure);
  }
}

/**
 * Capture a failed `fetch` call.
 *
 * @param request - the request that was issued
 * @param failure - the rejection reason and/or the non-2xx response
 *
 * @example
 * ```ts
 * import { captureFetchError } from '@codewithrajat/rm-logvault';
 *
 * const startedAt = Date.now();
 * const response = await fetch('/api/orders');
 * if (!response.ok) {
 *   captureFetchError({ method: 'GET', url: '/api/orders', startedAt }, { response });
 * }
 * ```
 */
export function captureFetchError(request: FetchRequestInfo, failure: FetchFailure): void {
  try {
    const classification = buildFetchErrorContext(request, failure);
    const status = classification.api.status ?? 0;
    const error = failure.error ?? new Error(`Request failed with status ${String(status)}`);
    captureError(error, {
      source: 'api',
      api: classification.api,
      category: classification.category,
      severity: classification.severity,
    });
  } catch (failure2) {
    reportInternalFailure('capture-fetch', failure2);
  }
}
