/**
 * Vue 3 adapter: a plugin that installs `errorHandler` and `warnHandler`.
 *
 * @remarks
 * Vue lets exactly one `app.config.errorHandler` exist. Installing a second one
 * silently discards the first, which is a classic way to break someone else's
 * error reporting. This adapter therefore **chains**: it captures the handler that
 * was already installed and calls it afterwards, so both run.
 *
 * @packageDocumentation
 */

import type { App } from 'vue';
import { captureError } from '../errors/captureError.js';
import type { ErrorContext } from '../errors/types.js';

/** Options for {@link createTelemetryVuePlugin}. */
export interface VueAdapterOptions {
  /** Extra context merged into every captured record. */
  readonly context?: ErrorContext | undefined;
  /** Also wrap `app.config.warnHandler`. Default `true`. */
  readonly captureWarnings?: boolean | undefined;
}

/** The object returned by {@link createTelemetryVuePlugin}. */
export interface TelemetryVuePlugin {
  install(app: App): void;
}

/**
 * Attach telemetry to a Vue application.
 *
 * @param app - the Vue application instance
 * @param options - see {@link VueAdapterOptions}
 *
 * @example
 * ```ts
 * import { createApp } from 'vue';
 * import { attachVueTelemetry } from '@codewithrajat/rm-logvault/vue';
 *
 * const app = createApp(App);
 * attachVueTelemetry(app, { context: { tags: { shell: 'checkout' } } });
 * app.mount('#app');
 * ```
 */
export function attachVueTelemetry(app: App, options: VueAdapterOptions = {}): void {
  try {
    const captureWarnings = options.captureWarnings ?? true;
    const context = options.context;

    const previousErrorHandler = app.config.errorHandler;

    app.config.errorHandler = (error: unknown, instance: unknown, info: string): void => {
      try {
        captureError(error, {
          source: 'vue',
          // `info` is Vue's lifecycle hook name (e.g. "render function"), which is
          // the closest thing Vue offers to a component stack.
          ...(typeof info === 'string' ? { extra: { vueInfo: info } } : {}),
          ...(context ?? {}),
        });
      } catch {
        // Reporting must never break the application.
      }

      // Chain: the application's own handler still runs, exactly once.
      if (typeof previousErrorHandler === 'function') {
        try {
          (previousErrorHandler as (e: unknown, i: unknown, info: string) => void)(
            error,
            instance,
            info,
          );
        } catch {
          // A throwing app handler is not our problem.
        }
      }
    };

    if (!captureWarnings) return;

    const previousWarnHandler = app.config.warnHandler;
    app.config.warnHandler = (message: string, instance: unknown, trace: string): void => {
      try {
        captureError(new Error(message), {
          source: 'vue',
          severity: 'warning',
          category: 'runtime',
          handled: true,
          tags: { framework: 'vue', kind: 'warning' },
          ...(typeof trace === 'string' && trace.length > 0 ? { extra: { vueTrace: trace } } : {}),
          ...(context ?? {}),
        });
      } catch {
        // ignore
      }

      if (typeof previousWarnHandler === 'function') {
        try {
          (previousWarnHandler as (m: string, i: unknown, trace: string) => void)(
            message,
            instance,
            trace,
          );
        } catch {
          // ignore
        }
      }
    };
  } catch {
    // A malformed app object must not break bootstrap.
  }
}

/**
 * Create a Vue plugin that installs telemetry.
 *
 * @param options - see {@link VueAdapterOptions}
 * @returns a plugin suitable for `app.use()`
 *
 * @example
 * ```ts
 * import { createApp } from 'vue';
 * import { createTelemetryVuePlugin } from '@codewithrajat/rm-logvault/vue';
 *
 * createApp(App).use(createTelemetryVuePlugin()).mount('#app');
 * ```
 */
export function createTelemetryVuePlugin(options: VueAdapterOptions = {}): TelemetryVuePlugin {
  return {
    install(app: App): void {
      attachVueTelemetry(app, options);
    },
  };
}
